import{_ as n,I as t,o as r,c as d,b6 as i,j as o,J as e,w as p}from"./chunks/framework.BUXTSoD9.js";const _=JSON.parse('{"title":"現代 AI 生圖 SaaS 開發實戰","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/assignments/modern-landing-page/index.md","filePath":"zh-tw/stage-2/assignments/modern-landing-page/index.md"}'),h={name:"zh-tw/stage-2/assignments/modern-landing-page/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="現代-ai-生圖-saas-開發實戰" tabindex="-1">現代 AI 生圖 SaaS 開發實戰 <a class="header-anchor" href="#現代-ai-生圖-saas-開發實戰" aria-label="Permalink to “現代 AI 生圖 SaaS 開發實戰”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本實戰項目要求你圍繞一份真實的 PRD（產品需求文檔），從零完成一個參考 Midjourney 體驗的 AI 生圖 SaaS 產品。你將完整經歷需求分析、項目拆解、迭代開發、聯調上線的全過程。</p><p>這是 Stage 2 的綜合實戰環節。在前面幾章中，你已經分別學習了前端頁面設計、後端接口開發、資料庫操作、支付集成等單項技能——這個項目要求你把它們全部串起來，交付一個可運行的產品原型。</p><h2 id="前置知識" tabindex="-1">前置知識 <a class="header-anchor" href="#前置知識" aria-label="Permalink to “前置知識”">​</a></h2><p>在開始本項目之前，你應該已經掌握以下內容：</p><ul><li>前端頁面設計與組件庫使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">現代組件庫</a>）</li><li>後端接口設計與開發（<a href="./../../backend/ai-interface-code/">接口程式碼編寫</a>）</li><li>資料庫基礎與 Supabase（<a href="./../../backend/database-supabase/">從資料庫到 Supabase</a>）</li><li>支付集成（<a href="./../../backend/stripe-payment/">Stripe 收費系統</a>）</li><li>Git 工作流與部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 應用</a>）</li></ul><h2 id="學習目標" tabindex="-1">學習目標 <a class="header-anchor" href="#學習目標" aria-label="Permalink to “學習目標”">​</a></h2><p>完成本實戰後，你將能夠：</p><ol><li>閱讀並理解一份真實的 PRD，從中提取開發任務清單</li><li>基於 PRD 拆分模塊，制定分步推進計劃</li><li>使用 AI 輔助完成前端骨架搭建和後端接口開發</li><li>對每個模塊進行驗證和迭代優化</li><li>完成端到端聯調，將項目從&quot;能跑&quot;推進到&quot;能交付&quot;</li></ol><h2 id="項目簡介" tabindex="-1">項目簡介 <a class="header-anchor" href="#項目簡介" aria-label="Permalink to “項目簡介”">​</a></h2><p>你要構建的產品是一個現代 AI 生圖 SaaS 平臺，包含三個子系統：</p><table tabindex="0"><thead><tr><th>子系統</th><th>職責</th></tr></thead><tbody><tr><td><strong>官網前臺</strong></td><td>產品介紹、定價、FAQ、註冊轉化</td></tr><tr><td><strong>用戶工作臺</strong></td><td>Prompt 輸入、圖片生成、圖庫、積分、套餐、社區互動</td></tr><tr><td><strong>後臺管理臺</strong></td><td>用戶管理、任務管理、支付管理、內容審核、SaaS 指標、系統監控</td></tr></tbody></table><p>後端需要支持以下核心能力：用戶鑑權、圖片生成任務、OSS 對象存儲、積分與套餐支付、圖片社交互動、運營資料監控。</p><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本項目的需求文檔在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-tw/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',15)),o("div",c,[e(s,null,{default:p(()=>[e(l,{active:0,items:[{title:"需求分析",description:"閱讀 PRD，提取頁面、模塊、資料模型和邊界"},{title:"搭建骨架",description:"用 AI 生成三套前端骨架（www / app / admin）"},{title:"迭代開發",description:"逐模塊補充接口、權限、支付、監控"},{title:"聯調上線",description:"端到端跑通，部署並準備演示"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-閱讀-prd" tabindex="-1">1.1 閱讀 PRD <a class="header-anchor" href="#_1-1-閱讀-prd" aria-label="Permalink to “1.1 閱讀 PRD”">​</a></h3><p>打開 PRD 文檔，重點回答以下問題：</p><ul><li>系統有幾個入口？各自覆蓋哪些頁面？</li><li>每個頁面的核心功能是什麼？</li><li>後端包含哪些模塊和資料庫表？</li><li>MVP 範圍是什麼？第一版哪些做，哪些不做？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上問題沒有明確答案，不要開始寫程式碼。需求理解不清楚是導致返工的最常見原因。</p></div><h3 id="_1-2-確認系統架構" tabindex="-1">1.2 確認系統架構 <a class="header-anchor" href="#_1-2-確認系統架構" aria-label="Permalink to “1.2 確認系統架構”">​</a></h3><p>根據 PRD 中的描述，梳理出系統的整體架構：</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;官網前臺&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;用戶工作臺&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;後臺管理臺&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;鑑權&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;圖片生成任務&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;OSS 對象存儲&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;資料庫&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;支付與套餐&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;分享 / 點贊 / 評論 / 轉發&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;SaaS 指標看板&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;API / DB / Provider 監控&quot;]</span></span></code></pre></div><p>建議你用自己的話把架構圖畫一遍，確認你對系統的理解是完整的。</p><h2 id="第二部分-搭建項目骨架" tabindex="-1">第二部分：搭建項目骨架 <a class="header-anchor" href="#第二部分-搭建項目骨架" aria-label="Permalink to “第二部分：搭建項目骨架”">​</a></h2><h3 id="_2-1-生成前端頁面" tabindex="-1">2.1 生成前端頁面 <a class="header-anchor" href="#_2-1-生成前端頁面" aria-label="Permalink to “2.1 生成前端頁面”">​</a></h3><p>使用 AI 先生成所有頁面的基本結構和假資料。這一步的目標是搭出資訊架構和路由，不需要接真實接口。</p><p>提示詞參考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請基於當前 PRD，幫我生成一個現代 AI 生圖 SaaS 的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 分成三個入口：www、app、admin</span></span>
<span class="line"><span>2. 官網包括：首頁、定價、FAQ</span></span>
<span class="line"><span>3. app 包括：登錄、註冊、生成工作臺、圖庫、套餐、積分、社區、作品詳情、個人中心</span></span>
<span class="line"><span>4. admin 包括：後臺首頁、用戶管理、任務管理、內容管理、套餐管理、支付訂單、運營配置、SaaS 指標、系統監控</span></span>
<span class="line"><span>5. 先只生成頁面結構和假資料，不接真實接口</span></span>
<span class="line"><span>6. 風格參考 Midjourney，簡潔、現代、帶產品感</span></span></code></pre></div><h3 id="_2-2-驗證頁面結構" tabindex="-1">2.2 驗證頁面結構 <a class="header-anchor" href="#_2-2-驗證頁面結構" aria-label="Permalink to “2.2 驗證頁面結構”">​</a></h3><p>骨架生成後，逐項檢查：</p><ul><li>[ ] 三個入口的路由是否獨立（<code>/</code>、<code>/app</code>、<code>/admin</code>）</li><li>[ ] 頁面數量是否與 PRD 一致</li><li>[ ] 每個頁面是否可以正常訪問和導航</li><li>[ ] 假資料是否展示了基本的 UI 狀態（列表、空狀態、表單等）</li></ul><h2 id="第三部分-迭代開發" tabindex="-1">第三部分：迭代開發 <a class="header-anchor" href="#第三部分-迭代開發" aria-label="Permalink to “第三部分：迭代開發”">​</a></h2><h3 id="_3-1-按模塊推進" tabindex="-1">3.1 按模塊推進 <a class="header-anchor" href="#_3-1-按模塊推進" aria-label="Permalink to “3.1 按模塊推進”">​</a></h3><p>在骨架的基礎上，按以下順序逐模塊補充功能：</p><ol><li><strong>鑑權</strong>：註冊、登錄、角色區分</li><li><strong>資料庫</strong>：資料表創建、讀寫接口</li><li><strong>核心業務</strong>：圖片生成任務、結果存儲</li><li><strong>OSS 存儲</strong>：圖片上傳與訪問</li><li><strong>支付</strong>：套餐、積分、Stripe 集成</li><li><strong>社交互動</strong>：分享、點贊、評論</li><li><strong>後臺管理</strong>：用戶管理、任務管理、內容審核</li><li><strong>資料監控</strong>：SaaS 指標看板、系統監控</li></ol><p>每完成一個模塊，使用下表進行自檢：</p><table tabindex="0"><thead><tr><th>檢查項</th><th>驗證方法</th></tr></thead><tbody><tr><td>頁面一致性</td><td>頁面數量、入口、功能是否符合 PRD</td></tr><tr><td>接口正確性</td><td>請求參數、返回結構、狀態處理是否合理</td></tr><tr><td>權限隔離</td><td>普通用戶和管理員是否互相隔離</td></tr><tr><td>資料一致性</td><td>資料庫、OSS、支付、積分是否對得上</td></tr><tr><td>可演示性</td><td>是否能給別人完整演示一條業務鏈路</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>如果發現 AI 生成的內容偏離了 PRD，不要整頁推翻重來，直接讓它修改具體模塊即可。</p></div><h3 id="_3-2-角色與分工" tabindex="-1">3.2 角色與分工 <a class="header-anchor" href="#_3-2-角色與分工" aria-label="Permalink to “3.2 角色與分工”">​</a></h3><p>在迭代過程中，你需要同時扮演三個角色：</p><ul><li><strong>產品經理</strong>：確認每個模塊的功能是否符合 PRD</li><li><strong>技術負責人</strong>：確認實現方案是否合理</li><li><strong>測試工程師</strong>：確認功能是否跑得通</li></ul><h2 id="第四部分-聯調與上線" tabindex="-1">第四部分：聯調與上線 <a class="header-anchor" href="#第四部分-聯調與上線" aria-label="Permalink to “第四部分：聯調與上線”">​</a></h2><h3 id="_4-1-端到端測試" tabindex="-1">4.1 端到端測試 <a class="header-anchor" href="#_4-1-端到端測試" aria-label="Permalink to “4.1 端到端測試”">​</a></h3><p>最後階段的重點不是補新頁面，而是把完整業務鏈路跑通。至少驗證以下場景：</p><ul><li>註冊 → 購買積分 → 生成圖片 → 查看歷史 → 分享互動</li><li>管理員登錄 → 查看用戶資料 → 查看任務統計 → 查看系統監控</li></ul><h3 id="_4-2-部署" tabindex="-1">4.2 部署 <a class="header-anchor" href="#_4-2-部署" aria-label="Permalink to “4.2 部署”">​</a></h3><p>將項目部署到公網環境，確保：</p><ul><li>環境變量配置完整</li><li>登錄回調地址正確</li><li>支付回調地址正確</li><li>頁面無缺失的 loading、空狀態、錯誤提示</li></ul><p>部署教程參考：<a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a>、<a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a>。</p><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本項目後，你需要提交以下內容：</p><ul><li>[ ] 可訪問的線上演示鏈接</li><li>[ ] 源碼倉庫鏈接（含 README）</li><li>[ ] PRD 文檔</li><li>[ ] 核心頁面截圖（官網首頁、生圖工作臺、圖庫、套餐頁、後臺首頁）</li><li>[ ] 60 秒演示影片（覆蓋註冊 → 生成 → 查看 → 後臺管理）</li></ul><p>README 至少包含：項目簡介、核心頁面說明、技術棧、本地啟動步驟、環境變量清單。</p><h2 id="評分標準" tabindex="-1">評分標準 <a class="header-anchor" href="#評分標準" aria-label="Permalink to “評分標準”">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>基本要求</th><th>進階要求</th></tr></thead><tbody><tr><td>PRD 對齊</td><td>頁面、功能、資料結構基本符合 PRD</td><td>能清晰說明每個設計決策與 PRD 的對應關係</td></tr><tr><td>產品閉環</td><td>註冊 → 購買積分 → 生成圖片 → 查看歷史 → 分享互動可跑通</td><td>支付狀態、積分餘額、生成次數資料一致</td></tr><tr><td>後臺能力</td><td>用戶、任務、支付、內容管理可查看</td><td>SaaS 指標看板和系統監控頁完整可用</td></tr><tr><td>工程完整度</td><td>前端、後端、資料庫、OSS、支付鏈路已接通</td><td>有錯誤處理、空狀態、loading 狀態</td></tr><tr><td>交付質量</td><td>可部署、可運行</td><td>README 清楚、演示影片結構完整</td></tr></tbody></table><h2 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/multi-product-ui/">參考 UI 設計規範設計頁面和按鈕</a></li><li><a href="./../../frontend/llm-skills-beautiful/">用 LLM 和 Skills 讓界面變好看</a></li><li><a href="./../../frontend/design-to-code/">從設計原型到項目程式碼</a></li><li><a href="./../../frontend/modern-component-library/">使用現代組件庫更新你的界面</a></li><li><a href="./../../backend/database-supabase/">從資料庫到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型輔助編寫接口程式碼與接口文檔</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a></li><li><a href="./../../backend/stripe-payment/">如何集成 Stripe 等收費系統</a></li></ul>`,43))])}const P=n(h,[["render",b]]);export{_ as __pageData,P as default};
